const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function dailyAccuracy(attempts){const days=new Map();for(const a of attempts){if(a.mode==='memorize')continue;const d=new Date(a.at),key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;if(!days.has(key))days.set(key,{label:d.toLocaleDateString(undefined,{month:'short',day:'numeric'}),correct:0,total:0});const day=days.get(key);day.total++;day.correct+=Number(a.correct);}return [...days].sort(([a],[b])=>a.localeCompare(b)).slice(-14).map(([,day])=>({...day,value:Math.round(day.correct/day.total*100)}));}
export function lineChart(points,label,target=null){
 if(!points.length)return `<div class="chart-empty">${escape(label==='Mock exam scores'?'Complete an exam to see your scores.':'Answer questions to start your accuracy chart.')}</div>`;
 const x=i=>40+(points.length===1?130:i/(points.length-1)*270),y=n=>140-n*1.1;
 const path=points.map((p,i)=>`${i?'L':'M'}${x(i)} ${y(p.value)}`).join(' ');
 return `<svg class="trend-chart" viewBox="0 0 340 180" role="img" aria-label="${escape(label)}"><title>${escape(label)}</title>${[0,50,100].map(n=>`<line class="chart-grid" x1="40" y1="${y(n)}" x2="310" y2="${y(n)}"/><text x="30" y="${y(n)+4}" text-anchor="end">${n}%</text>`).join('')}${target!==null?`<line class="chart-target" x1="40" y1="${y(target)}" x2="310" y2="${y(target)}"/>`:''}${points.length>1?`<path class="chart-area" d="${path} L${x(points.length-1)} 140 L${x(0)} 140Z"/><path class="chart-line" d="${path}"/>`:''}${points.map((p,i)=>`<circle class="chart-point" cx="${x(i)}" cy="${y(p.value)}" r="4"><title>${escape(p.label)}: ${p.value}%${p.total?` (${p.correct}/${p.total})`:''}</title></circle>`).join('')}<text x="40" y="167">${escape(points[0].label)}</text>${points.length>1?`<text x="310" y="167" text-anchor="end">${escape(points.at(-1).label)}</text>`:''}</svg><details class="chart-values"><summary>View values</summary><div>${points.map(p=>`<div class="between small"><span>${escape(p.label)}${p.total?` · ${p.total} answers`:''}</span><strong>${p.value}%</strong></div>`).join('')}</div></details>`;
}
export function coverageChart(covered,total){const ratio=total?Math.min(1,covered/total):0,c=2*Math.PI*48;return `<div class="coverage-chart"><svg viewBox="0 0 130 130" role="img" aria-label="${covered} of ${total} base questions practiced"><circle class="coverage-base" cx="65" cy="65" r="48"/><circle class="coverage-fill" cx="65" cy="65" r="48" stroke-dasharray="${c*ratio} ${c}" transform="rotate(-90 65 65)"/><text class="coverage-number" x="65" y="65" text-anchor="middle">${Math.round(ratio*100)}%</text><text x="65" y="83" text-anchor="middle">covered</text></svg><div><strong>${covered} practiced</strong><p class="small muted">${Math.max(0,total-covered)} to explore</p><span class="small muted">${total} base questions</span></div></div>`;}
